namespace sv_12bba09b164848e4a863a602dfecd75f.Services;

public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "WH-001";

    public event Action? OnChange;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A — Main Distribution"),
        ("WH-002", "Warehouse B — East Regional"),
        ("WH-003", "Warehouse C — West Regional"),
        ("WH-004", "Warehouse D — Cold Storage"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (SelectedWarehouseId == warehouseId) return;
        SelectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_12bba09b164848e4a863a602dfecd75f.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentLowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query that returns the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate latency and return a random count between 0 and 15
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Refreshes the alert count for the given warehouse and notifies all subscribers.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        CurrentLowStockCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }
}

