@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@GetWarehouseName()</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card border-danger">
            <div class="card-body text-center">
                <h5 class="card-title text-danger">Low Stock Alerts</h5>
                <p class="display-4">@AlertService.CurrentLowStockCount</p>
                <p class="text-muted">Items below minimum levels</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="mb-0">
                    @if (_polling)
                    {
                        <span class="badge bg-success">Active — every 10s</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary">Inactive</span>
                    }
                </p>
                <p class="text-muted mt-2">Last refreshed: @_lastRefresh?.ToString("HH:mm:ss")</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Site</h5>
                <p class="mb-0"><code>@Warehouse.SelectedWarehouseId</code></p>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private bool _polling;
    private DateTime? _lastRefresh;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        Warehouse.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(() =>
        {
            _lastRefresh = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertCountChanged += _alertHandler;

        await StartPollingAsync();
    }

    private async Task OnWarehouseChanged()
    {
        // Immediately refresh when warehouse changes
        await AlertService.RefreshAlertCountAsync(Warehouse.SelectedWarehouseId);
        StateHasChanged();
    }

    private async Task StartPollingAsync()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _polling = true;

        // Initial fetch
        await AlertService.RefreshAlertCountAsync(Warehouse.SelectedWarehouseId);
        _lastRefresh = DateTime.Now;

        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAlertCountAsync(Warehouse.SelectedWarehouseId);
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose
        }
    }

    private string GetWarehouseName()
    {
        return WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == Warehouse.SelectedWarehouseId).Name ?? "Unknown";
    }

    public void Dispose()
    {
        _polling = false;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();

        if (_warehouseHandler is not null)
            Warehouse.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

