                        <span class="badge bg-success">Active — every 10s</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary">Inactive</span>
                    }
                </p>
                <p class="text-muted mt-2">Last refreshed: @_lastRefresh?.ToString("HH:mm:ss")</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Site</h5>
                <p class="mb-0"><code>@Warehouse.SelectedWarehouseId</code></p>
            </div>
