@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private bool _polling;
    private DateTime? _lastRefresh;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        Warehouse.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(() =>
        {
            _lastRefresh = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertCountChanged += _alertHandler;

        await StartPollingAsync();
    }

    private async Task OnWarehouseChanged()
    {
        // Immediately refresh when warehouse changes
        await AlertService.RefreshAlertCountAsync(Warehouse.SelectedWarehouseId);
        StateHasChanged();
    }

    private async Task StartPollingAsync()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _polling = true;

        // Initial fetch
        await AlertService.RefreshAlertCountAsync(Warehouse.SelectedWarehouseId);
        _lastRefresh = DateTime.Now;

        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAlertCountAsync(Warehouse.SelectedWarehouseId);
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose
        }
    }

    private string GetWarehouseName()
    {
        return WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == Warehouse.SelectedWarehouseId).Name ?? "Unknown";
    }

    public void Dispose()
    {
        _polling = false;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();

        if (_warehouseHandler is not null)
            Warehouse.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

